import pandas as pd
import json

# ── Read and normalize each source ──────────────────────────────────────────

# Source A (JSON) — highest priority
df_a = pd.read_json('/data/source_a/users.json')
df_a = df_a.rename(columns={
    'id': 'user_id',
    'full_name': 'name',
    'email': 'email',
    'registration_date': 'created_date',
    'status': 'status',
})
df_a['_source'] = 'a'

# Source B (CSV)
df_b = pd.read_csv('/data/source_b/users.csv')
df_b = df_b.rename(columns={
    'user_id': 'user_id',
    'name': 'name',
    'email_address': 'email',
    'created_at': 'created_date',
    'is_active': 'status',
})
df_b['status'] = df_b['status'].map({'true': 'active', 'false': 'inactive'})
df_b['_source'] = 'b'

# Source C (Parquet)
df_c = pd.read_parquet('/data/source_c/users.parquet')
df_c = df_c.rename(columns={
    'userId': 'user_id',
    'userName': 'name',
    'email': 'email',
    'joined': 'created_date',
    'active': 'status',
})
df_c['status'] = df_c['status'].apply(lambda x: 'active' if x else 'inactive')
df_c['_source'] = 'c'

# ── Build lookups keyed by (user_id, field) → source → value ──────────────

FIELDS = ['name', 'email', 'created_date', 'status']
SOURCES = ['a', 'b', 'c']

all_data = {}  # { (user_id, field): { 'a': val, 'b': val, 'c': val } }

for df, src in [(df_a, 'a'), (df_b, 'b'), (df_c, 'c')]:
    for _, row in df.iterrows():
        uid = int(row['user_id'])
        for f in FIELDS:
            val = row.get(f)
            if pd.isna(val):
                continue
            key = (uid, f)
            if key not in all_data:
                all_data[key] = {}
            all_data[key][src] = val

# ── Merge records (priority: a > b > c) and detect conflicts ──────────────

merged_records = []
conflicts = []

all_user_ids = sorted(set(k[0] for k in all_data))

for uid in all_user_ids:
    record = {'user_id': uid}
    for f in FIELDS:
        vals = all_data.get((uid, f), {})
        if not vals:
            record[f] = None
            continue

        # Pick highest-priority value
        for src in SOURCES:
            if src in vals:
                record[f] = vals[src]
                break

        # Detect conflict: more than one source with values, not all equal
        if len(vals) > 1:
            unique_vals = set(str(v) for v in vals.values())
            if len(unique_vals) > 1:
                conflicts.append({
                    'user_id': uid,
                    'field': f,
                    'values': {
                        'source_a': vals.get('a'),
                        'source_b': vals.get('b'),
                        'source_c': vals.get('c'),
                    },
                    'selected': record[f],
                })

    merged_records.append(record)

# ── Build output DataFrames ─────────────────────────────────────────────────

df_out = pd.DataFrame(merged_records)
df_out['user_id'] = df_out['user_id'].astype(int)

# Normalize date format
def normalize_date(val):
    if pd.isna(val):
        return None
    s = str(val).strip()
    # Already YYYY-MM-DD or can be parsed
    try:
        return pd.Timestamp(s).strftime('%Y-%m-%d')
    except Exception:
        return s

df_out['created_date'] = df_out['created_date'].apply(normalize_date)

# Ensure all output columns exist
for col in ['user_id', 'name', 'email', 'created_date', 'status']:
    if col not in df_out.columns:
        df_out[col] = None

df_out = df_out[['user_id', 'name', 'email', 'created_date', 'status']]

# ── Write outputs ──────────────────────────────────────────────────────────

df_out.to_parquet('/app/merged_users.parquet', index=False)

report = {
    'total_conflicts': len(conflicts),
    'conflicts': conflicts,
}
with open('/app/conflicts.json', 'w') as f:
    json.dump(report, f, indent=2, default=str)

print(f"Merged {len(df_out)} unique users")
print(f"Detected {len(conflicts)} field conflicts")
print("Output written to /app/merged_users.parquet and /app/conflicts.json")

